import{z as d,x as p,o as r,c as A,q as t,j as E,D as i,d as e,s,S as l,b as o}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"io_uring","description":"","frontmatter":{"title":"io_uring","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/io-uring.md","filePath":"cs/io-uring.md","lastUpdated":1791063341000}'),u={name:"cs/io-uring.md"};function _(c,a,f,m,B,g){const n=p("Mermaid");return r(),A("div",null,[a[2]||(a[2]=t('<h1 id="io-uring" tabindex="-1">io_uring <a class="header-anchor" href="#io-uring" aria-label="Permalink to &quot;io_uring&quot;">​</a></h1><div class="epigraph"><p>用户与内核共享提交队列和完成队列：一次陷入可提交多条 I/O，完成不必为每个请求再进系统调用。</p><footer>—— 据 Axboe, Efficient IO with io_uring, 2019；Linux io_uring 文档整理</footer></div><p><a href="/cs/epoll">上一课</a> 仍是「就绪再 read」，每次读写一条系统调用。<a href="/cs/blk-mq">blk-mq</a> 已能并行提交块请求。缺口是把提交与完成做成<strong>环形缓冲</strong>：程序把 SQE 写进共享页，内核写 CQE。本课讲机制与和 epoll 的分工，不发明 arXiv 编号。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>高 IOPS 时，陷入与 <code>copy_from_user</code> 成为主成本。aio 接口历史上限制多、完成模型别扭。io_uring：mmap 两圈队列，可选 <code>IORING_SETUP_SQPOLL</code> 用内核线程轮询提交（权衡 CPU）。缺口不是重做 bio，而是用户可见的队列与一次 <code>io_uring_enter</code> 的批处理。文件、套接字、稍后的超时都可成为 op。</p><p><span class="marginnote">固定文件与固定缓冲减少每次把 fd/地址翻译进内核的开销。完成顺序不必等于提交顺序。本课不写利用错误注册缓冲的步骤。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>io_uring_setup</code> 得到 fd 与映射地址。用户填 SQE（操作码、fd、缓冲、偏移）。内核取出执行，结果进 CQE（结果码、用户 data）。程序可以 epoll 这个 uring fd，或再 enter 等待完成。块设备路径最终仍可走 bio；本课不重画 DMA。</p>',8)),(r(),E(l,null,{default:i(()=>[s(n,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SQ%5B%22%E7%94%A8%E6%88%B7%E5%86%99%20SQE%22%5D%20--%3E%20ENT%5B%22enter%20%E6%88%96%20SQPOLL%22%5D%0A%20%20ENT%20--%3E%20K%5B%22%E5%86%85%E6%A0%B8%E6%89%A7%E8%A1%8C%22%5D%0A%20%20K%20--%3E%20CQ%5B%22%E5%86%85%E6%A0%B8%E5%86%99%20CQE%22%5D%0A%20%20CQ%20--%3E%20APP%5B%22%E7%94%A8%E6%88%B7%E6%94%B6%E5%89%B2%E5%AE%8C%E6%88%90%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("h2",{id:"机制",tabindex:"-1"},[e("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=o("p",null,[e("io_uring 把系统调用路径从「每请求一次」改成「每批一次」，并让完成与提交解耦，便于流水线。它不取消 "),o("a",{href:"/cs/vfs"},"VFS"),e(" 与权限检查：每个 op 仍以发出进程的身份执行。与共享内存 IPC 不同：这里共享的是请求描述，不是业务文件内容本身（除非 op 指向共享缓冲）。")],-1)),(r(),E(l,null,{default:i(()=>[s(n,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20SUB%5B%22mmap%20%E5%87%BA%E7%9A%84%E4%B8%A4%E5%9C%88%E5%85%B1%E4%BA%AB%E7%8E%AF%22%5D%20--%3E%20SQT%5B%22%E7%94%A8%E6%88%B7%E6%8E%A8%E8%BF%9B%20SQ%20tail%3A%20%E6%94%92%203%20%E6%9D%A1%20SQE%22%5D%0A%20%20SQT%20--%3E%20ONE%5B%22%E4%B8%80%E6%AC%A1%20io_uring_enter%22%5D%0A%20%20ONE%20--%3E%20K%5B%22%E5%86%85%E6%A0%B8%E6%8C%89%20head%20%E9%80%90%E6%9D%A1%E6%89%A7%E8%A1%8C%22%5D%0A%20%20K%20--%3E%20CQT%5B%22%E5%86%85%E6%A0%B8%E6%8E%A8%E8%BF%9B%20CQ%20tail%3A%203%20%E6%9D%A1%20CQE%22%5D%0A%20%20CQT%20--%3E%20R%5B%22%E7%94%A8%E6%88%B7%E6%94%B6%E5%89%B2%2C%20%E4%BB%8D%E6%97%A0%E9%9C%80%E5%86%8D%E9%99%B7%E5%85%A5%22%5D%0A"})]),fallback:i(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p><span class="marginnote">数字实例：NVMe 盘跑到每秒 100 万次 I/O 时，「每请求一次系统调用」意味着每秒约 100 万次陷入，按每次 400 纳秒算光陷入就要烧掉约 0.4 秒 CPU（单核四成）；每批 32 条时陷入次数降到约 3.1 万次，这笔税缩到百分之一量级。</span></p><p><span class="marginnote">直觉类比：SQ 像餐厅的传菜单转轮，你把点单（SQE）一张张夹上去；服务员（内核）按顺序取单做菜，做好放上另一个出菜转轮（CQ），你从那头取餐。你不用每道菜都跑进后厨喊一声（系统调用）。</span></p><p><span class="marginnote">常见误区：初学者容易以为「零系统调用」等于「绕过内核检查」。实际每个操作仍以调用进程的身份过 VFS 权限、文件偏移、rlimit 这些关卡，io_uring 只是把「往返车程」省了，安检一样没少。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把所有 opcode 列成表。不保证旧内核有 uring。下一课离开事件 I/O，进入内核如何数时间：滴答与 jiffies——超时与调度一直在用，尚未当课。</p><p>后课默认：I/O 可批量异步完成。内核的滴答计数与 HZ，下一课 jiffies。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>io_uring 用共享 SQ/CQ 批量提交与收割 I/O。</li><li>仍走 VFS 权限；底层可接 bio。</li><li>内核时间基准是 jiffies 的缺口。</li><li>出处：Axboe, <em>Efficient IO with io_uring</em>（2019）；Linux <code>io_uring</code> 文档。</li></ul>',8))])}const C=d(u,[["render",_]]);export{S as __pageData,C as default};
